int main(void) {
    qlstack *s = qlstack_new();
    if (!s) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 1; i <= 3; i++) {
        if (!qlstack_push(s, i)) {
            fprintf(stderr, "out of memory\n");
            exit(EXIT_FAILURE);
        }
    }
    printf("size %zu, top elem %d\n", qlstack_size(s), s->top->elem);

    int x;
    qlstack_pop(s, &x);
    printf("popped %d, size %zu, top elem %d\n", x, qlstack_size(s), s->top->elem);

    qlstack_pop(s, NULL);          // pop and throw the element away
    printf("popped (discarded), size %zu, top elem %d\n", qlstack_size(s), s->top->elem);

    while (!qlstack_is_empty(s)) {  // pop whatever is left
        qlstack_pop(s, &x);
        printf("popped %d, size %zu\n", x, qlstack_size(s));
    }
    printf("empty? %d, top is NULL? %d\n", qlstack_is_empty(s), s->top == NULL);
    free(s);                        // the stack struct itself (no nodes are left)
    return 0;
}

