#include <stdio.h>
#include <stdlib.h>

struct node {
    int elem;
    struct node *next;
};

int main(void) {
    struct node *first = NULL;
    for (int i = 1; i <= 3; i++) {          // build 3 -> 2 -> 1
        struct node *n = malloc(sizeof(struct node));
        if (!n) {
            exit(EXIT_FAILURE);
        }
        n->elem = i;
        n->next = first;
        first = n;
    }
    // BROKEN: n->next is read AFTER free(n)
    for (struct node *n = first; n != NULL; n = n->next) {
        free(n);
    }
    printf("done\n");
    return 0;
}

blocks.text:
### Printing a stack

`qlstack_print` walks the nodes too, from the top to the bottom. It takes two optional strings: `pre` is printed before the stack and `post` after it, and either may be `NULL` (then it is skipped). The stack itself is printed as `top : 3, 2, 1 : bottom`.

```c
void qlstack_print(const char *pre, const qlstack *s, const char *post) {
    if (pre) {
        printf("%s", pre);
    }
    printf("top : ");
    if (!qlstack_is_empty(s)) {
        struct node *n = s->top;
        printf("%d", n->elem);
        n = n->next;
        while (n) {
            printf(", %d", n->elem);
            n = n->next;
        }
    }
    printf(" : bottom");
    if (post) {
        printf("%s", post);
    }
}
```

- The first element is printed on its own, then every further one with `", %d"` in front: that puts commas **between** the elements and none at the end.
- An empty stack prints `top : ` and then ` : bottom`, so you see `top :  : bottom` with **two** spaces between the colons.
- `const qlstack *s`: printing does not change the stack. `s` itself must not be `NULL` (undefined behaviour).

