// Removes every element: frees all nodes, but keeps the stack struct
// so that s is an empty stack that can be used again.
// Does nothing if s is NULL.
void qlstack_clear(qlstack *s) {
    if (!s) {
        return;
    }
    struct node *n = s->top;
    while (n) {
        struct node *next = n->next;   // save the link BEFORE freeing n
        free(n);
        n = next;
    }
    s->top = NULL;                     // the stack is empty now
    s->size = 0;
}

