#include <stdio.h>
#include <stdlib.h>

struct plate {
    int weight;
    struct plate *below;
};

struct pile {
    struct plate *top;
    size_t count;
};

struct pile *pile_new(void) {
    struct pile *p = malloc(sizeof(struct pile));
    if (!p) {
        return NULL;
    }
    p->top = NULL;
    p->count = 0;
    return p;
}

int pile_push(struct pile *p, int weight) {
    struct plate *n = malloc(sizeof(struct plate));
    if (!n) {
        return 0;
    }
    n->weight = weight;
    n->below = p->top;
    p->top = n;
    p->count++;
    return 1;
}

// Removes the top plate and frees it. Stores its weight in *out
// (if out is not NULL) and returns 1. Returns 0 if the pile is empty.
int pile_pop(struct pile *p, int *out) {
    if (p->top == NULL) {
        return 0;
    }
    struct plate *old = p->top;
    int w = old->weight;
    p->top = old->below;
    p->count--;
    free(old);
    if (out) {
        *out = w;
    }
    return 1;
}

// Frees every plate and then the pile itself. Does nothing if p is NULL.
void pile_free(struct pile *p) {
    if (!p) {
        return;
    }
    struct plate *n = p->top;
    while (n != NULL) {
        struct plate *next = n->below;
        free(n);
        n = next;
    }
    free(p);
}

int main(void) {
    struct pile *p = pile_new();
    if (!p) {
        return 1;
    }
    for (int w = 5; w <= 25; w += 5) {
        if (!pile_push(p, w)) {
            pile_free(p);
            return 1;
        }
    }
    int w;
    while (p->count > 2 && pile_pop(p, &w)) {
        printf("took %d, %zu left\n", w, p->count);
    }
    pile_pop(p, NULL);
    printf("top weight now %d\n", p->top->weight);
    pile_free(p);
    return 0;
}

write.prompt:
You are given these types for a linked stack of `int`s:

```c
typedef struct node node;
struct node {
    int elem;
    node *next;
};

typedef struct stack stack;
struct stack {
    node *top;      // the top node, NULL if the stack is empty
    size_t size;    // the number of elements
};
```

Write the function

```c
int pop_sum(stack *s, size_t k, int *sum)
```

that removes the top `k` elements of the stack pointed at by `s`, frees each removed node, stores the **sum** of the removed elements in `*sum`, and returns 1. If the stack has fewer than `k` elements, the function must change nothing (not the stack, not `*sum`) and return 0. For `k == 0` it stores 0 and returns 1. You may assume `s` and `sum` are not `NULL`.

Example: for the stack 5, 7, 1, 3 (top first), `pop_sum(s, 2, &t)` returns 1, sets `t` to 12 and leaves 1, 3 with size 2; then `pop_sum(s, 3, &t)` returns 0 and changes nothing.

write.solution:
int pop_sum(stack *s, size_t k, int *sum) {
    if (s->size < k) {
        return 0;
    }
    int total = 0;
    for (size_t i = 0; i < k; i++) {
        node *old = s->top;
        total += old->elem;
        s->top = old->next;
        free(old);
    }
    s->size -= k;
    *sum = total;
    return 1;
}
